  <h1>Window.open Handler Demo</h1>
  <p>Main Window ID: <span id="window-id">loading...</span></p>

  <button id="btn-basic">Basic window.open()</button>
  <button id="btn-sized">Sized Window (600x400)</button>
  <button id="btn-positioned">Positioned Window (100,100)</button>
  <button id="btn-modal">Modal Dialog</button>
  <button id="btn-external">External Link (https://example.com)</button>
  <button id="btn-named">Named Window ("popup")</button>
  <button id="btn-no-toolbar">No Toolbar/Location</button>

  <div class="log" id="log"></div>

  <script>
    const log = document.getElementById('log');
    function addLog(msg) {
      log.textContent += `[${new Date().toLocaleTimeString()}] ${msg}\n`;
      log.scrollTop = log.scrollHeight;
    }

    window.electronAPI.getMainWindowId().then(id => {
      document.getElementById('window-id').textContent = id;
    });

    window.electronAPI.onChildWindowClosed((data) => {
      addLog(`Child window closed: ${data.name}`);
    });

    document.getElementById('btn-basic').onclick = () => {
      window.open('child.html', '_blank');
      addLog('Opened basic child window');
    };

    document.getElementById('btn-sized').onclick = () => {
      window.open('child.html', '_blank', 'width=600,height=400');
      addLog('Opened sized window (600x400)');
    };

    document.getElementById('btn-positioned').onclick = () => {
      window.open('child.html', '_blank', 'left=100,top=100,width=500,height=300');
      addLog('Opened positioned window (100,100)');
    };

    document.getElementById('btn-modal').onclick = () => {
      window.open('child.html', '_blank', 'modal=yes,width=400,height=300');
      addLog('Opened modal dialog');
    };

    document.getElementById('btn-external').onclick = () => {
      window.open('https://example.com', '_blank');
      addLog('Attempted to open external link');
    };

    document.getElementById('btn-named').onclick = () => {
      window.open('child.html', 'popup', 'width=500,height=400');
      addLog('Opened named window "popup"');
    };

    document.getElementById('btn-no-toolbar').onclick = () => {
      window.open('child.html', '_blank', 'toolbar=no,location=no,width=500,height=400');
      addLog('Opened window without toolbar/location');
    };
  </script>
